export const siteScript = `
  document.documentElement.classList.add('js-ready');

  document.querySelector('.menu-toggle')?.addEventListener('click', () => {
    const links = document.querySelector('.nav-links');
    const visible = links.style.display === 'flex';
    links.style.display = visible ? 'none' : 'flex';
    links.style.cssText += visible ? '' : 'position:absolute; top:100%; left:0; right:0; background:var(--paper); flex-direction:column; padding:1.25rem 1.75rem; border-bottom:1px solid var(--line); gap:1rem; z-index:39;';
  });

  const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  // Scroll reveal
  const revealEls = document.querySelectorAll('.reveal');
  if ('IntersectionObserver' in window && revealEls.length) {
    const io = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) { entry.target.classList.add('is-visible'); io.unobserve(entry.target); }
      });
    }, { threshold: 0.1, rootMargin: '0px 0px -6% 0px' });
    revealEls.forEach(el => io.observe(el));
  } else {
    revealEls.forEach(el => el.classList.add('is-visible'));
  }

  // Método — sincroniza los guiones de progreso con la tarjeta apilada visible
  const methodCards = document.querySelectorAll('.method-card-wrap');
  const methodDashes = document.querySelectorAll('.method-progress .dash');
  if ('IntersectionObserver' in window && methodCards.length) {
    const methodIO = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          const step = entry.target.getAttribute('data-card');
          methodDashes.forEach(d => d.classList.toggle('active', d.getAttribute('data-dash') === step));
        }
      });
    }, { threshold: 0, rootMargin: '-45% 0px -45% 0px' });
    methodCards.forEach(el => methodIO.observe(el));
  }

  // Scroll progress bar
  const scrollBar = document.getElementById('scrollBar');
  const updateScrollBar = () => {
    if (!scrollBar) return;
    const h = document.documentElement;
    const scrolled = h.scrollTop / (h.scrollHeight - h.clientHeight || 1);
    scrollBar.style.width = (Math.min(1, Math.max(0, scrolled)) * 100) + '%';
  };
  window.addEventListener('scroll', updateScrollBar, { passive: true });
  updateScrollBar();

  // Hero — titular en palabras, con entrada escalonada
  const heroH1 = document.querySelector('.hero h1');
  if (heroH1 && !reduceMotion) {
    const nodes = Array.from(heroH1.childNodes);
    heroH1.innerHTML = '';
    let wordIndex = 0;
    nodes.forEach(node => {
      if (node.nodeType === Node.TEXT_NODE) {
        node.textContent.split(/(\\s+)/).forEach(chunk => {
          if (chunk.trim() === '') { heroH1.appendChild(document.createTextNode(chunk)); return; }
          const span = document.createElement('span');
          span.className = 'word';
          span.textContent = chunk;
          span.style.transitionDelay = (wordIndex * 45) + 'ms';
          wordIndex++;
          heroH1.appendChild(span);
        });
      } else {
        node.classList.add('word');
        node.style.transitionDelay = (wordIndex * 45) + 'ms';
        wordIndex++;
        heroH1.appendChild(node);
      }
    });
    requestAnimationFrame(() => requestAnimationFrame(() => {
      heroH1.querySelectorAll('.word').forEach(w => w.classList.add('in'));
    }));
  }

  // Hero — paralaje sutil de los resplandores según el cursor
  const hero = document.querySelector('.hero');
  const glow1 = document.querySelector('.hero-glow.g1');
  const glow2 = document.querySelector('.hero-glow.g2');
  if (hero && glow1 && glow2 && !reduceMotion && matchMedia('(hover: hover)').matches) {
    hero.addEventListener('mousemove', (e) => {
      const r = hero.getBoundingClientRect();
      const px = (e.clientX - r.left) / r.width - 0.5;
      const py = (e.clientY - r.top) / r.height - 0.5;
      glow1.style.transform = 'translate(' + (px * 40) + 'px,' + (py * 40) + 'px)';
      glow2.style.transform = 'translate(' + (px * -30) + 'px,' + (py * -30) + 'px)';
    });
  }

  // Botones magnéticos — leve atracción hacia el cursor
  if (!reduceMotion && matchMedia('(hover: hover)').matches) {
    document.querySelectorAll('.btn').forEach(btn => {
      btn.classList.add('btn-magnetic');
      btn.addEventListener('mousemove', (e) => {
        const r = btn.getBoundingClientRect();
        const mx = (e.clientX - r.left) / r.width - 0.5;
        const my = (e.clientY - r.top) / r.height - 0.5;
        btn.style.transform = 'translate(' + (mx * 10) + 'px,' + (my * 10) + 'px)';
      });
      btn.addEventListener('mouseleave', () => { btn.style.transform = ''; });
    });
  }

  // Tarjetas con leve inclinación 3D al pasar el cursor
  if (!reduceMotion && matchMedia('(hover: hover)').matches) {
    document.querySelectorAll('.value-card, .service-card, .highlight-cell, .trust-card, .method-card, .resource-card').forEach(card => {
      card.classList.add('tilt-el');
      card.addEventListener('mousemove', (e) => {
        const r = card.getBoundingClientRect();
        const mx = (e.clientX - r.left) / r.width - 0.5;
        const my = (e.clientY - r.top) / r.height - 0.5;
        card.style.transform = 'perspective(900px) rotateX(' + (my * -5) + 'deg) rotateY(' + (mx * 6) + 'deg) translateY(-4px)';
      });
      card.addEventListener('mouseleave', () => { card.style.transform = ''; });
    });
  }

  // Cifras animadas al entrar en pantalla
  if ('IntersectionObserver' in window) {
    if (!reduceMotion) {
      document.querySelectorAll('.num[data-count]').forEach(el => {
        el.textContent = '0' + (el.getAttribute('data-suffix') || '');
      });
    }
    const countIO = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (!entry.isIntersecting) return;
        const el = entry.target;
        const target = parseInt(el.getAttribute('data-count'), 10);
        const suffix = el.getAttribute('data-suffix') || '';
        countIO.unobserve(el);
        if (reduceMotion) { el.textContent = target + suffix; return; }
        const duration = 1100;
        const start = performance.now();
        const step = (now) => {
          const p = Math.min(1, (now - start) / duration);
          const eased = 1 - Math.pow(1 - p, 3);
          el.textContent = Math.round(eased * target) + suffix;
          if (p < 1) requestAnimationFrame(step);
        };
        requestAnimationFrame(step);
      });
    }, { threshold: 0.6 });
    document.querySelectorAll('.num[data-count]').forEach(el => countIO.observe(el));
  }
`;
